importScripts('https://www.gstatic.com/firebasejs/10.13.2/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.13.2/firebase-messaging-compat.js');

// Generated by scripts/build_web.sh — do not edit manually.
// Source values come from lib/firebase_options.dart (generated by flutterfire configure).
firebase.initializeApp({
  apiKey:            '%%FCM_API_KEY%%',
  authDomain:        '%%FCM_AUTH_DOMAIN%%',
  projectId:         '%%FCM_PROJECT_ID%%',
  storageBucket:     '%%FCM_STORAGE_BUCKET%%',
  messagingSenderId: '%%FCM_SENDER_ID%%',
  appId:             '%%FCM_APP_ID%%',
});

const messaging = firebase.messaging();

// Handles push notifications when the web app is in the background or closed.
messaging.onBackgroundMessage((payload) => {
  const title = payload.notification?.title ?? payload.data?.title ?? '';
  const body  = payload.notification?.body  ?? payload.data?.body  ?? '';
  if (!title && !body) return;
  self.registration.showNotification(title, {
    body,
    icon: '/icons/Icon-192.png',
  });
});
